        .cmd_op_o   (w_cmd_op),
        .cmd_rank_o (w_cmd_rank),
        .cmd_bank_o (w_cmd_bank),
        .cmd_row_o  (w_cmd_row),
        .cmd_col_o  (w_cmd_col),
        .cmd_ap_o   (w_cmd_ap),
        .busy_o     ()
    );

    // ======================================================================
    // Plane 2b: training wrapper (ZQ + write-leveling)
    // ======================================================================
    scoria_training_plane #(
        .NUM_CS(NUM_CS),
        .CSW   ((NUM_CS > 1) ? $clog2(NUM_CS) : 1)
    ) u_train_plane (
        .mc_clk             (aclk),
        .mc_rst_n           (w_aresetn),
        .init_done_i        (init_done_o),
        .memtype_i          (memtype_i),
        .zq_enable_i        (zq_enable_i),
        .zq_interval_i      (zq_interval_i),
        .t_zqcs_i           (t_zqcs_i),
        .zq_placement_i     (zq_placement_i),
        .zq_overdue_max_i   (zq_overdue_max_i),
        .zq_req_o           (w_zq_req),
        .zq_grant_i         (w_zq_grant),
        .zq_busy_o          (zq_busy_o),
        .zq_total_o         (zq_total_o),
        .zq_interval_cnt_o  (zq_interval_cnt_o),
        .zq_overdue_o       (zq_overdue_o),
        .wrlvl_en_i         (w_wrlvl_en),
        .wrlvl_strobe_i     (wrlvl_strobe_i),
        .wrlvl_cs_sel_i     (wrlvl_cs_sel_i),
        .t_wldqsen_i        (t_wldqsen_i),
        .t_wlmrd_i          (t_wlmrd_i),
        .t_wlmrd_max_i      (t_wlmrd_max_i),
        .t_wlo_i            (t_wlo_i),
        .t_wloe_i           (t_wloe_i),
        .dfi_phylvl_req_cs_n_o (w_wl_req_cs_n),
        .dfi_phylvl_ack_cs_n_i (w_wl_ack_cs_n),
        .dfi_phy_wrlvl_cs_n_o  (w_wl_mode_cs_n),
        .dfi_wrlvl_strobe_o    (w_wl_strobe),
        .wrlvl_prime_dq_i      (w_wl_prime_dq),
        .wrlvl_result_valid_o  (wrlvl_result_valid_o),
        .wrlvl_result_o        (wrlvl_result_o),
        .wrlvl_attempts_o      (wrlvl_attempts_o),
        .wrlvl_flips_o         (wrlvl_flips_o),
        .wrlvl_timeout_o       (wrlvl_timeout_o),
        .wrlvl_ever_done_o     (wrlvl_ever_done_o),
        .wrlvl_state_o         (wrlvl_state_o)
    );

    // ======================================================================
    // Plane 3: DFI plane (single CDC + datapath)
    // ======================================================================
    // DFI v3.1 data-phase chip selects. One rank, so rank 0 is the only legal
    // selection and these are constant -- driven by the controller rather than
    // tied off by the integrator, because presenting them is the controller's
    // side of the v3.1 contract (scoria TASK-005). Multi-rank must drive these
    // from the granted command's rank, in step with dfi_cs_n.
    assign dfi_wrdata_cs_n_o = '0;
    assign dfi_rddata_cs_n_o = '0;

    mc_dfi_3p1_plane #(
        .NUM_RANKS       (NUM_RANKS),
        .NUM_CS          (NUM_CS),
        .NUM_BANKS       (NUM_BANKS),
        .ROW_WIDTH       (ROW_WIDTH),
        .COL_WIDTH       (COL_WIDTH),
        .DFI_RATE        (DFI_RATE),
        .DRAM_BEAT_WIDTH (DRAM_BEAT_WIDTH),
        .DFI_BEATS_PER_BURST  (BL_PUMICE),
        .N_SUBCMD        (N_SUBCMD),
        .SUB_COL_STRIDE  (SUB_COL_STRIDE),
        .SUB_PHASE_STRIDE(SUB_PHASE_STRIDE),
        .SUBW_MAX        (SUBW_MAX),
        .BURST_WORDS     (BURST_WORDS),
        // TASK-004: set EXPLICITLY. The plane's default was BL_WORDS, and a
        // parameter nobody sets is how that went unnoticed.
        .RD_EN_CYC       (RD_EN_CYC_CORE),
        // The read return has NO backpressure at the PHY (rddata_valid cannot
        // stall), so the aligner's tracking and the return CDC FIFO must cover
        // every read the ring can hold in flight: RD_RET_DEPTH reads x
        // BURST_WORDS DFI words each. Sized here, asserted in the aligner.
        .RD_MAX_OUTSTANDING(RD_RET_DEPTH),
        .RD_FIFO_DEPTH   (RD_RET_DEPTH * BURST_WORDS),
        // Write data is STAGED for CMD_DELAY cycles before its command arrives
        // (that is the point), so the wrdata CDC must hold CMD_DELAY/BURST_WORDS
        // + 2 bursts without stalling the CAM drain -- or the lag comes back.
        .WD_FIFO_DEPTH   (32),
        .CMD_HISTORY_EN  (CMD_HISTORY_EN),
        .HIST_T_RFC      (HIST_T_RFC_CORE),
        .HIST_T_RTW      (HIST_T_RTW_CORE),
        .HIST_T_WTR      (HIST_T_WTR_CORE)
    ) u_dfi_plane (
        .ctl_clk            (aclk),
        .ctl_rstn           (w_aresetn),
        .cmd_valid_i        (w_cmd_v),
        .cmd_ready_o        (w_cmd_rdy),
        .cmd_data_i         (w_cmd_data),
        .wd_valid_i         (w_cm_v),
        .wd_ready_o         (w_cm_rdy),
        .wd_data_i          ({w_cm_last, w_cm_strb, w_cm_data}),
        .rd_valid_o         (w_ret_v),
        .rd_ready_i         (w_ret_rdy),
        .rd_data_o          ({w_ret_last, w_ret_resp, w_ret_data}),
        .init_start_i       (w_init_start),
        .init_complete_o    (w_init_complete),
        .dfi_clk            (dfi_clk),
        .dfi_rstn           (w_aresetn_dfi),
        .memtype_i          (memtype_i),
        .rd_phase_i         (rd_phase_i),
        .wr_phase_i         (wr_phase_i),
        .t_phy_wrlat_i      (t_phy_wrlat_i),
        .t_rddata_en_i      (t_rddata_en_i),
        .gear_i             (gear_i),
        .n_subcmd_i         (w_n_subcmd),
        .sub_col_stride_i   (w_sub_col_stride),
        .sub_phase_stride_i (w_sub_phase_stride),
        .dfi_address_o      (dfi_address_o),
        .dfi_bank_o         (dfi_bank_o),
        .dfi_cas_n_o        (dfi_cas_n_o),
        .dfi_ras_n_o        (dfi_ras_n_o),
        .dfi_we_n_o         (dfi_we_n_o),
        .dfi_cs_n_o         (dfi_cs_n_o),
        .dfi_odt_o          (dfi_odt_o),
        .dfi_wrdata_o       (dfi_wrdata_o),
        .dfi_wrdata_en_o    (dfi_wrdata_en_o),
        .dfi_wrdata_mask_o  (dfi_wrdata_mask_o),
        .dfi_rddata_en_o    (dfi_rddata_en_o),
        .dfi_rddata_i       (dfi_rddata_i),
        .dfi_rddata_valid_i (dfi_rddata_valid_i),
        .dfi_init_start_o   (dfi_init_start_o),
        .dfi_init_complete_i(dfi_init_complete_i),
        // write leveling: ctl_clk side from the scheduler, dfi_clk side to the pins
        .wl_req_cs_n_i      (w_wl_req_cs_n),
        .wl_wrlvl_cs_n_i    (w_wl_mode_cs_n),
        .wl_strobe_i        (w_wl_strobe),
        .wl_ack_cs_n_o      (w_wl_ack_cs_n),
        .wl_prime_dq_o      (w_wl_prime_dq),
        .dfi_phylvl_req_cs_n_o (dfi_phylvl_req_cs_n_o),
        .dfi_phylvl_ack_cs_n_i (dfi_phylvl_ack_cs_n_i),
        .dfi_phy_wrlvl_cs_n_o  (dfi_phy_wrlvl_cs_n_o),
        .dfi_wrlvl_strobe_o    (dfi_wrlvl_strobe_o),
        .dfi_prime_dq_i        (dfi_prime_dq_i)
    );

endmodule : scoria_core
